      out.write("<script>\n");
      out.write("// Carousel functionality\n");
      out.write("let slideIndex = 0;\n");
      out.write("const slides = document.querySelectorAll('.amazon-carousel-slide');\n");
      out.write("const dots = document.querySelectorAll('.dot');\n");
      out.write("\n");
      out.write("function showSlide(n) {\n");
      out.write("    if (n >= slides.length) slideIndex = 0;\n");
      out.write("    if (n < 0) slideIndex = slides.length - 1;\n");
      out.write("    \n");
      out.write("    slides.forEach(slide => slide.classList.remove('active'));\n");
      out.write("    dots.forEach(dot => dot.classList.remove('active'));\n");
      out.write("    \n");
      out.write("    if (slides[slideIndex]) slides[slideIndex].classList.add('active');\n");
      out.write("    if (dots[slideIndex]) dots[slideIndex].classList.add('active');\n");
      out.write("}\n");
      out.write("\n");
      out.write("function changeSlide(n) {\n");
      out.write("    slideIndex += n;\n");
      out.write("    showSlide(slideIndex);\n");
      out.write("}\n");
      out.write("\n");
      out.write("function currentSlide(n) {\n");
      out.write("    slideIndex = n - 1;\n");
      out.write("    showSlide(slideIndex);\n");
      out.write("}\n");
      out.write("\n");
      out.write("// Auto-advance carousel\n");
      out.write("setInterval(() => {\n");
      out.write("    changeSlide(1);\n");
      out.write("}, 5000);\n");
      out.write("\n");
      out.write("// Initialize\n");
      out.write("showSlide(slideIndex);\n");
      out.write("</script>\n");
